# -*- coding: utf-8 -*-
"""dpr_rollback_v652_to_v651.py — 把 dpr_suite v652（R-1008-12／R-1008-1）逐位元組還原成 v651。
用法：python3 dpr_rollback_v652_to_v651.py dpr_suite.py dpr_suite_v651.py
預期印出 SHA256 5a81f158…（v651）。內含：tdt_link v6 原檔、build_dpr v615→v614 反向編輯、suite 文字反向編輯；_PACK 以 suite 自身 pack() 重打。"""
import sys,os,ast,lzma,base64,hashlib,tempfile,shutil,subprocess
D=ast.literal_eval(lzma.decompress(base64.b64decode("")).decode())
src,dst=sys.argv[1],sys.argv[2]
tmp=tempfile.mkdtemp()
shutil.copy(src,os.path.join(tmp,'dpr_suite.py'))
subprocess.check_call([sys.executable,'dpr_suite.py','restore','--dir',tmp],cwd=tmp,stdout=subprocess.DEVNULL)
open(os.path.join(tmp,'tdt_link.py'),'wb').write(D['tdt6'])
p=os.path.join(tmp,'build_dpr.py'); b=open(p,encoding='utf-8').read()
for n,o in D['EB']:
    assert b.count(n)==1,'builder 反向編輯定位失敗'; b=b.replace(n,o,1)
open(p,'w',encoding='utf-8').write(b)
sp=os.path.join(tmp,'dpr_suite.py'); s=open(sp,encoding='utf-8').read()
for n,o in D['ES']:
    assert s.count(n)==1,'suite 反向編輯定位失敗'; s=s.replace(n,o,1)
open(sp,'w',encoding='utf-8').write(s)
subprocess.check_call([sys.executable,'dpr_suite.py','pack','--dir',tmp],cwd=tmp,stdout=subprocess.DEVNULL)
shutil.copy(sp,dst)
print('SHA256',hashlib.sha256(open(dst,'rb').read()).hexdigest())
